INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "张从宾", "aliases": ["張從賓"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：张从宾，侍卫步军都指挥使、忠正节度使。", "biography": null, "status": "draft", "id": "9a3c8e19-d709-5a20-b9dd-ef00849d161d"}, {"name": "宋廷浩", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": 937, "description": "后晋巡检使。937年七月，张从宾进攻汜水关时将他杀害。", "biography": null, "status": "draft", "id": "33e3df11-a84b-5a7d-8dd6-06f3e1b4ae4d"}, {"name": "石敬瑭", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷271贞明五年条所见人物：石敬瑭。", "biography": null, "status": "draft", "id": "bf42d98c-7477-5be1-a767-867fe26cf617"}, {"name": "桑维翰", "aliases": ["桑維翰"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：桑维翰，主张自全、求援者。", "biography": null, "status": "draft", "id": "5132e50a-3ce2-55d5-8f89-fdccd6bf4f02"}, {"name": "范延光", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷272同光元年条所见人物：范延光。", "biography": null, "status": "draft", "id": "6889e460-4b23-5243-9441-b5c3a78da98f"}, {"name": "娄继英", "aliases": ["婁繼英"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷273同光二年条所见人物：娄继英。", "biography": null, "status": "draft", "id": "f6c6be57-cfd2-54e0-a3d3-f6de4e943c92"}, {"name": "尹晖", "aliases": ["尹暉"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：尹晖，严卫步军左厢指挥使、偏裨。", "biography": null, "status": "draft", "id": "bd7deb48-309d-5bdc-ab41-85bbc59444ea"}, {"name": "温延浚", "aliases": ["溫延濬"], "era": "五代十国", "birth_year": null, "death_year": 937, "description": "温韬的儿子、温延沼的弟弟。937年在许州响应范延光，后来投奔张从宾，被张从宾杀害。", "biography": null, "status": "draft", "id": "7f68c1b0-3115-5691-ac86-36f6c9a4d9a1"}, {"name": "温延沼", "aliases": ["溫延沼"], "era": "五代十国", "birth_year": null, "death_year": 937, "description": "温韬的儿子，温延浚、温延衮的兄长。937年在许州响应范延光，曾阻止兄弟杀害娄继英，后来被张从宾杀害。", "biography": null, "status": "draft", "id": "8cbb5d11-7c7d-5ca2-b1d6-93bfb989ff5b"}, {"name": "温延衮", "aliases": ["溫延衮", "溫延袞"], "era": "五代十国", "birth_year": null, "death_year": 937, "description": "温韬的儿子、温延沼的弟弟。937年在许州响应范延光，后来投奔张从宾，被张从宾杀害。", "biography": null, "status": "draft", "id": "bb96bb07-bd3a-5a09-b212-17c6c68886bf"}, {"name": "温韬", "aliases": ["李彦韬", "李彥韜", "温昭图", "溫昭圖", "溫韜"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷267开平二年条所见人物：温韬。", "biography": null, "status": "draft", "id": "6884d5fe-c806-51f1-9b78-a9c93f17733f"}, {"name": "苌从简", "aliases": ["萇從簡", "李绍琼", "李紹瓊"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275同光四年条所见人物：苌从简，忠武节度使，复苌从简姓名。", "biography": null, "status": "draft", "id": "e5c9931f-7b97-52cf-866a-8dd001266296"}, {"name": "白奉进", "aliases": ["白奉進"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "云州人，后晋将领。937年以侍卫马军都指挥使、昭信节度使身份，奉命率一千五百骑兵驻守白马津。", "biography": null, "status": "draft", "id": "7ff1aba2-0da0-5683-8991-bd1b69aa366d"}, {"name": "符彦饶", "aliases": ["符彥饒", "李彦饶", "李彥饒"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275同光四年条所见人物：符彦饶，被逼为帅、要求停止焚掠者。", "biography": null, "status": "draft", "id": "fab16ea8-291a-5d04-86b9-d463c9d60303"}, {"name": "马万", "aliases": ["馬萬"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋奉国左厢都指挥使。937年滑州军乱时，在卢顺密劝说后参与擒获符彦饶，随后被任命为义成节度使。", "biography": null, "status": "draft", "id": "f6395e7e-44dc-5315-b53a-907daff9dec7"}, {"name": "卢顺密", "aliases": ["盧順密"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷272同光元年条所见人物：卢顺密。", "biography": null, "status": "draft", "id": "6cf9344d-7825-5c5d-8cde-d8a12a293ab8"}, {"name": "方太", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：方太，讨平军乱者。", "biography": null, "status": "draft", "id": "f3df25e6-d0a6-57cc-8996-e5d57af4f5ef"}, {"name": "杨檀", "aliases": ["楊檀", "杨光远", "楊光遠"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：杨檀，冀州刺史、反对遣归者。", "biography": null, "status": "draft", "id": "54ec3b10-aece-5189-91a8-84a03c5691a3"}, {"name": "刘知远", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷271贞明五年条所见人物：刘知远。", "biography": null, "status": "draft", "id": "69fa3b4b-2f0d-5799-bbf5-e378af9816e1"}, {"name": "高行周", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷268乾化三年条所见人物：高行周。", "biography": null, "status": "draft", "id": "659c5f83-09bc-5282-8f02-4c7fa0a62729"}, {"name": "杜重威", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "朔州人，后晋将领，妻子是石敬瑭的妹妹乐平长公主。937年以护圣都指挥使身份率军驻卫州。", "biography": null, "status": "draft", "id": "e5e23c10-447f-5238-bc56-f376300f9bac"}, {"name": "侯益", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275同光四年条所见人物：侯益，平遥前直指挥使、脱身返洛者。", "biography": null, "status": "draft", "id": "d164db58-b751-53af-9dac-d5112662da44"}, {"name": "冯晖", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷263天复二年条所见人物：冯晖。", "biography": null, "status": "draft", "id": "e59e2b00-2873-5968-ab4c-938628164ecf"}, {"name": "孙锐", "aliases": ["孫銳"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "范延光的元随左都押牙。范延光把军府事务交给他处理。937年与冯晖共同劝逼范延光起兵，随后担任兵马都监。", "biography": null, "status": "draft", "id": "03455fb4-2e7f-5785-8536-8eb1c52c226a"}, {"name": "张延播", "aliases": ["張延播"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋官员，任东都副留守、都巡检使。937年张从宾反叛后让他主持河南府事务。", "biography": null, "status": "draft", "id": "16d3d321-f393-528d-bc49-1f9ba0e819e0"}, {"name": "张继祚", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷268乾化元年条所见人物：张继祚。", "biography": null, "status": "draft", "id": "901ce89b-5d00-51b8-8cef-3f5ea0bc8684"}, {"name": "李涛（后晋史馆修撰）", "aliases": ["李濤（后晋史馆修撰）"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋史馆修撰。937年以张全义重建洛阳的功绩为由，请求减轻对张继祚家族的牵连。", "biography": null, "status": "draft", "id": "f0911500-ce63-5f4f-9a7d-327831b6466a"}, {"name": "张全义", "aliases": [], "era": "唐末五代十国", "birth_year": null, "death_year": null, "description": "据《资治通鉴》，907年在“后梁加封钱镠、张全义、刘隐等”中为受封者。", "biography": null, "status": "draft", "id": "3d89e670-5812-57eb-a061-8aaea77bd5e8"}, {"name": "张晖（博州守将）", "aliases": ["張暉（博州守将）"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "937年负责博州的守将，向杨光远献城投降。原文未在此处说明具体官衔和家世。", "biography": null, "status": "draft", "id": "595a7575-933a-5659-8729-3c7ca60b3d5b"}, {"name": "王晖（安州威和指挥使）", "aliases": ["王暉（安州威和指挥使）"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋安州威和指挥使。937年杀死安远节度使周瑰，自行掌管军府，准备根据范延光胜败决定依附或逃往吴国。", "biography": null, "status": "draft", "id": "45a72072-bb39-5411-99db-123a3029fbc5"}, {"name": "周瑰", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：周瑰，部将、获都押衙者。", "biography": null, "status": "draft", "id": "a22b68ef-f112-519c-bd58-bfffd84cadef"}, {"name": "李金全", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：李金全，前节度使、多次献马者。", "biography": null, "status": "draft", "id": "13205047-3c88-59d8-9900-ef435bd6e59a"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "张从宾攻汜水关，杀死巡检使宋廷浩", "start_year": 937, "end_year": 937, "time_original": "937年七月，具体日期未记载", "dynasty": "五代十国", "description": "张从宾攻汜水关，杀死巡检使宋廷浩。", "phases": [], "location_name": "汜水关", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "e26708a1-723f-582a-9b4c-dcfd22d742be"}, {"title": "石敬瑭准备率轻骑避往晋阳", "start_year": 937, "end_year": 937, "time_original": "937年七月，具体日期未记载", "dynasty": "五代十国", "description": "石敬瑭准备率轻骑避往晋阳。", "phases": [], "location_name": "大梁至晋阳的计划路线", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "5c8788a2-5399-5748-8149-f6cc419770cf"}, {"title": "桑维翰劝石敬瑭等待，石敬瑭停止避走计划", "start_year": 937, "end_year": 937, "time_original": "937年七月，具体日期未记载", "dynasty": "五代十国", "description": "桑维翰叩头劝谏，认为叛军虽声势强盛，却难以持久，请石敬瑭稍作等待。石敬瑭因此停止避往晋阳的计划。", "phases": [], "location_name": "大梁", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "bda2e39c-3c27-5e1c-85df-55d7d7be8f28"}, {"title": "范延光以蜡丸密信招引娄继英、尹晖及温氏三兄弟响应", "start_year": 937, "end_year": 937, "time_original": "937年七月，具体日期未记载", "dynasty": "五代十国", "description": "范延光以蜡丸密信招引娄继英、尹晖及温氏三兄弟响应。", "phases": [], "location_name": "大梁、许州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "0246cd28-3b01-5102-892d-0212bf24be13"}, {"title": "范延光命温氏兄弟夺取许州，温氏聚集千人", "start_year": 937, "end_year": 937, "