2540af"}, {"title": "苌从简严密戒备，温氏兄弟无法起兵", "start_year": 937, "end_year": 937, "time_original": "937年七月，具体日期未记载", "dynasty": "五代十国", "description": "苌从简严密戒备，温氏兄弟无法起兵。", "phases": [], "location_name": "许州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "c180c7c0-f209-5f36-aae2-b0a395f6b4f9"}, {"title": "温氏兄弟想杀娄继英自证清白，温延沼阻止", "start_year": 937, "end_year": 937, "time_original": "937年七月，具体日期未记载", "dynasty": "五代十国", "description": "温氏兄弟想杀娄继英自证清白，温延沼阻止。", "phases": [], "location_name": "许州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "998a9d2a-2f73-5d06-a858-2c25f0e98cac"}, {"title": "温氏兄弟与娄继英一同投奔张从宾", "start_year": 937, "end_year": 937, "time_original": "937年七月，具体日期未记载", "dynasty": "五代十国", "description": "温氏兄弟与娄继英一同投奔张从宾。", "phases": [], "location_name": "张从宾军中", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "5010885f-ccb3-5804-aea1-2fd570b97198"}, {"title": "娄继英劝张从宾捕杀温氏三兄弟", "start_year": 937, "end_year": 937, "time_original": "937年七月，具体日期未记载", "dynasty": "五代十国", "description": "娄继英劝张从宾捕杀温氏三兄弟。", "phases": [], "location_name": "张从宾军中", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "41c32e47-bc41-5211-8729-30c720a6afe6"}, {"title": "白奉进处死五名夜间劫掠军士", "start_year": 937, "end_year": 937, "time_original": "937年七月，具体日期未记载", "dynasty": "五代十国", "description": "白奉进在滑州捕获五名夜间劫掠军士，三人属自己部队、两人属符彦饶部队，全部处死。", "phases": [], "location_name": "滑州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "98f74a57-b958-5388-a36f-a60055a99bf0"}, {"title": "符彦饶不满白奉进越过自己处刑，二人发生争执", "start_year": 937, "end_year": 937, "time_original": "937年七月，具体日期未记载", "dynasty": "五代十国", "description": "符彦饶因白奉进未经告知处死自己的军士而发怒。次日白奉进带几名骑兵来道歉，认为违法军士不应区分所属；争执后反问符彦饶是否想与范延光一同反叛，随即起身，符彦饶没有挽留。", "phases": [], "location_name": "滑州牙署", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "0eae56e7-7e50-55ff-9459-14ed274d02fe"}, {"title": "符彦饶帐下军士捕杀白奉进", "start_year": 937, "end_year": 937, "time_original": "937年七月，具体日期未记载", "dynasty": "五代十国", "description": "符彦饶帐下军士捕杀白奉进。", "phases": [], "location_name": "滑州牙署", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "7e2d2dcf-3350-5bbf-9f05-e962e970bbfe"}, {"title": "白奉进随骑呼喊报信，滑州诸军武装喧乱", "start_year": 937, "end_year": 937, "time_original": "937年七月，具体日期未记载", "dynasty": "五代十国", "description": "白奉进随骑呼喊报信，滑州诸军武装喧乱。", "phases": [], "location_name": "滑州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "87003945-1c87-5277-a79d-ed8ed72dbd5f"}, {"title": "卢顺密劝马万擒符彦饶，制止他参与军乱", "start_year": 937, "end_year": 937, "time_original": "937年七月，具体日期未记载", "dynasty": "五代十国", "description": "马万原准备率步兵参与军乱。卢顺密劝他共同擒符彦饶送交皇帝，提醒军士家属都在大梁，并表示服从者受赏、违命者被杀。卢顺密判断符彦饶与魏州通谋，这属于他在劝说中的判断。", "phases": [], "location_name": "滑州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "307f2cbd-a023-59f0-be61-7ef1b42debd9"}, {"title": "卢顺密杀死数名呼喊跳跃的军士，压住骚乱", "start_year": 937, "end_year": 937, "time_original": "937年七月，具体日期未记载", "dynasty": "五代十国", "description": "卢顺密杀死数名呼喊跳跃的军士，压住骚