year": 937, "time_original": "937年七月，具体日期未记载", "dynasty": "五代十国", "description": "魏州、孟州、滑州接连动乱，石敬瑭向刘知远问计。刘知远以晋阳旧事和当前兵力、契丹关系安慰他，建议皇帝以恩安抚将相，自己以军纪管束士兵。", "phases": [], "location_name": "大梁", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "1b5bcfb1-1a97-5ba4-95f8-bf2d4fb8f87c"}, {"title": "刘知远严设军纪，宿卫军队不敢触犯", "start_year": 937, "end_year": 937, "time_original": "937年七月，具体日期未记载", "dynasty": "五代十国", "description": "刘知远严设军纪，宿卫军队不敢触犯。", "phases": [], "location_name": "大梁", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "0dd6c38d-384b-555f-85ff-700397a22a72"}, {"title": "刘知远杀死偷一包纸钱的军士", "start_year": 937, "end_year": 937, "time_original": "937年七月，具体日期未记载", "dynasty": "五代十国", "description": "一名军士偷了一包祭祀用纸钱，被主管者捕获。左右请求宽释，刘知远说要惩罚偷窃之心、不计物品价值，最终将其处死。史书记载军士因此畏惧服从。", "phases": [], "location_name": "大梁", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "c872f407-00df-5133-a2a0-f6edb03891c5"}, {"title": "杨光远被任命为魏府行营都招讨使并主持行府", "start_year": 937, "end_year": 937, "time_original": "937年七月乙卯", "dynasty": "五代十国", "description": "杨光远被任命为魏府行营都招讨使并主持行府。", "phases": [], "location_name": "五代十国", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "9d5f82b9-08d6-56af-a3f9-bbcbae287dbe"}, {"title": "高行周被任命为河南尹和东京留守", "start_year": 937, "end_year": 937, "time_original": "937年七月乙卯", "dynasty": "五代十国", "description": "高行周被任命为河南尹和东京留守。", "phases": [], "location_name": "五代十国", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名