ft", "id": "af4f5abf-f3ea-53ea-a19d-c822b6a445af", "subject_id": "fedb9e57-a696-57f4-9f94-f29e007a7876", "source_id": "cc007ffa-0d92-56e5-9c30-c70f558d191c"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "石敬瑭：拒绝接受范延光请罪。", "citation": "卷281·后晋天福二年（937；七月条下）·zztj-v281-y0937-p042·原文件第47行", "note": "原文：戊寅，杨光远以闻，帝不许。；核对说明：参与身份依据本句；人名沿用已有主体，原文不改字。", "status": "draft", "id": "5bb85d24-03cc-5d98-83d0-1dc77343a343", "subject_id": "ec6e790c-07bc-5d81-b74c-e33bb4acfab4", "source_id": "cc007ffa-0d92-56e5-9c30-c70f558d191c"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "范延光：请罪未获接受。", "citation": "卷281·后晋天福二年（937；七月条下）·zztj-v281-y0937-p042·原文件第47行", "note": "原文：戊寅，杨光远以闻，帝不许。；核对说明：参与身份依据本句；人名沿用已有主体，原文不改字。", "status": "draft", "id": "0e86e457-2fe7-51f2-803b-14c3af7ec9fa", "subject_id": "9aa67e2e-8519-5a38-a85d-83fee5f63275", "source_id": "cc007ffa-0d92-56e5-9c30-c70f558d191c"}, {"subject_table": "person", "field_path": "description", "claim_text": "后晋巡检使。937年七月，张从宾进攻汜水关时将他杀害。", "citation": "卷281·后晋天福二年（937；七月条下）·zztj-v281-y0937-p035·原文件第40行", "note": "原文：秋，七月，张从宾攻汜水，杀巡检使宋廷浩。；核对说明：简介按本段身份与行动整理；温氏长幼另由《新五代史》同传明文补证，马万任官另见本批第38段。限定名用于区别同名人，不添加会碰撞的裸名别名。", "status": "draft", "id": "1b0f789c-b189-523f-b899-2e9b74384d10", "subject_id": "33e3df11-a84b-5a7d-8dd6-06f3e1b4ae4d", "source_id": "e84d096f-85d1-5bb4-8532-79f46629b49b"}, {"subject_table": "person", "field_path": "description", "claim_text": "温韬的儿子、温延沼的弟弟。937年在许州响应范延光，后来投奔张从宾，被张从宾杀害。", "citation": "卷281·后晋天福二年（937；七月条下）·zztj-v281-y0937-p036·原文件第41行", "note": "原文：范延光遣使以蜡丸招诱失职者，右武卫上将军娄继英、右卫大将军尹晖在大梁，温韬之子延浚、延沼、延衮居许州，皆应之。延光令延浚兄弟取许州，聚徒已及千人。继英、晖事泄，皆出走，壬子，敕以延光奸谋，诬污忠良，自今获延光谍人，赏获者，杀谍人，禁蜡书，勿以闻。晖将奔吴，为人所杀。继英奔许州，依温氏。忠武节度使苌从简盛为之备，延浚等不得发，欲杀继英以自明，延沼止之，遂同奔张从宾。继英知其谋，劝从宾执三温，皆斩之。；核对说明：简介按本段身份与行动整理；温氏长幼另由《新五代史》同传明文补证，马万任官另见本批第38段。限定名用于区别同名人，不添加会碰撞的裸名别名。", "status": "draft", "id": "fb47b3a5-487e-59c9-a818-3f80657e4a16", "subject_id": "7f68c1b0-3115-5691-ac86-36f6c9a4d9a1", "source_id": "e84d096f-85d1-5bb4-8532-79f46629b49b"}, {"subject_table": "person", "field_path": "description", "claim_text": "温韬的儿子，温延浚、温延衮的兄长。937年在许州响应范延光，曾阻止兄弟杀害娄继英，后来被张从宾杀害。", "citation": "卷281·后晋天福二年（937；七月条下）·zztj-v281-y0937-p036·原文件第41行", "note": "原文：范延光遣使以蜡丸招诱失职者，右武卫上将军娄继英、右卫大将军尹晖在大梁，温韬之子延浚、延沼、延衮居许州，皆应之。延光令延浚兄弟取许州，聚徒已及千人。继英、晖事泄，皆出走，壬子，敕以延光奸谋，诬污忠良，自今获延光谍人，赏获者，杀谍人，禁蜡书，勿以闻。晖将奔吴，为人所杀。继英奔许州，依温氏。忠武节度使苌从简盛为之备，延浚等不得发，欲杀继英以自明，延沼止之，遂同奔张从宾。继英知其谋，劝从宾执三温，皆斩之。；核对说明：简介按本段身份与行动整理；温氏长幼另由《新五代史》同传明文补证，马万任官另见本批第38段。限定名用于区别同名人，不添加会碰撞的裸名别名。", "status": "draft", "id": "6c0dccf2-2a22-5b96-8f2c-45c4a86cb3fe", "subject_id": "8cbb5d11-7c7d-5ca2-b1d6-93bfb989ff5b", "source_id": "e84d096f-85d1-5bb4-8532-79f46629b49b"}, {"subject_table": "person", "field_path": "description", "claim_text": "温韬的儿子、温延沼的弟弟。937年在许州响应范延光，后来投奔张从宾，被张从宾杀害。", "citation": "卷281·后晋天福二年（937；七月条下）·zztj-v281-y0937-p036·原文件第41行", "note": "原文：范延光遣使以蜡丸招诱失职者，右武卫上将军娄继英、右卫大将军尹晖在大梁，温韬之子延浚、延沼、延衮居许州，皆应之。延光令延浚兄弟取许州，聚徒已及千人。继英、晖事泄，皆出走，壬子，敕以延光奸谋，诬污忠良，自今获延光谍人，赏获者，杀谍人，禁蜡书，勿以闻。晖将奔吴，为人所杀。继英奔许州，依温氏。忠武节度使苌从简盛为之备，延浚等不得发，欲杀继英以自明，延沼止之，遂同奔张从宾。继英知其谋，劝从宾执三温，皆斩之。；核对说明：简介按本段身份与行动整理；温氏长幼另由《新五代史》同传明文补证，马万任官另见本批第38段。限定名用于区别同名人，不添加会碰撞的裸名别名。", "status": "draft", "id": "84ea5a9b-17e0-5ba4-943b-7acdeeef8a24", "subject_id": "bb96bb07-bd3a-5a09-b212-17c6c68886bf", "source_id": "e84d096f-85d1-5bb4-8532-79f46629b49b"}, {"subject_table": "person", "field_path": "description", "claim_text": "后晋奉国左厢都指挥使。937年滑州军乱时，在卢顺密劝说后参与擒获符彦饶，随后被任命为义成节度使。", "citation": "卷281·后晋天福二年（937；七月条下）·zztj-v281-y0937-p037·原文件第42行", "note": "原文：奉国左厢都指挥使马万惶惑不知所为，帅步兵欲从乱，遇右厢都指挥使卢顺密帅部出营，厉声谓万曰：“符公擅杀白公，必与魏城通谋。此去行宫才二百里，吾辈及军士家属皆在大梁，奈何不思报国，乃欲助乱，自求族灭乎！今日当共擒符公，送天子，立大功。军士从命者赏，违命者诛，勿复疑也！”万部兵尚有呼跃者，顺密杀数人，众莫敢动。万不得已从之，与奉国都虞侯方太等共攻牙城，执彦饶，令太部送大梁。；核对说明：简介按本段身份与行动整理；温氏长幼另由《新五代史》同传明文补证，马万任官另见本批第38段。限定名用于区别同名人，不添加会碰撞的裸名别名。", "status": "draft", "id": "cdde7778-3236-5a99-a76d-626e73710e7e", "subject_id": "f6395e7e-44dc-5315-b53a-907daff9dec7", "source_id": "7f2cfe03-fa83-5c6a-905e-dd27f332ad79"}, {"subject_table": "person", "field_path": "description", "claim_text": "937年负责博州的守将，向杨光远献城投降。原文未在此处说明具体官衔和家世。", "citation": "卷281·后晋天福二年（937；七月条下）·zztj-v281-y0937-p040·原文件第45行", "note": "原文：杨光远奏知博州张晖举城降。；核对说明：简介按本段身份与行动整理；温氏长幼另由《新五代史》同传明文补证，马万任官另见本批第38段。限定名用于区别同名人，不添加会碰撞的裸名别名。", "status": "draft", "id": "2a65e9e2-1edc-5db2-a204-bceb9743f4d1", "subject_id": "595a7575-933a-5659-8729-3c7ca60b3d5b", "source_id": "7f2cfe03-fa83-5c6a-905e-dd27f332ad79"}, {"subject_table": "person", "field_path": "description", "claim_text": "后晋史馆修撰。937年以张全义重建洛阳的功绩为由，请求减轻对张继祚家族的牵连。", "citation": "卷281·后晋天福二年（937；七月条下）·zztj-v281-y0937-p038·原文件第43行", "note": "原文：史馆修撰李涛上言，张全义有再造洛邑之功，乞免其族，乃止诛继祚妻子。；核对说明：简介按本段身份与行动整理；温氏长幼另由《新五代史》同传明文补证，马万任官另见本批第38段。限定名用于区别同名人，不添加会碰撞的裸名别名。", "status": "draft", "id": "dc8b924f-75f9-5f3e-a282-952e1c20f95c", "subject_id": "f0911500-ce63-5f4f-9a7d-327831b6466a", "source_id": "7f2cfe03-fa83-5c6a-905e-dd27f332ad79"}, {"subject_table": "person", "field_path": "description", "claim_text": "后晋安州威和指挥使。937年杀死安远节度使周瑰，自行掌管军府，准备根据范延光胜败决定依附或逃往吴国。", "citation": "卷281·后晋天福二年（937；七月条下）·zztj-v281-y0937-p041·原文件第46行", "note": "原文：安州威和指挥使王晖闻范延光作乱，杀安远节度使周瑰，自领军府，欲俟延光胜则附之，败则渡江奔吴。；核对说明：简介按本段身份与行动整理；温氏长幼另由《新五代史》同传明文补证，马万任官另见本批第38段。限定名用于区别同名人，不添加会碰撞的裸名别名。", "status": "draft", "id": "a10b8390-a7ba-59d5-bd08-9f6d154dee6f", "subject_id": "45a72072-bb39-5411-99db-123a3029fbc5", "source_id": "7f2cfe03-fa83-5c6a-905e-dd27f332ad79"}, {"subject_table": "person", "field_path": "death_year", "claim_text": "宋廷浩于937年七月条所记事件中死亡。", "citation": "卷281·后晋天福二年（937；七月条下）·zztj-v281-y0937-p035·原文件第40行", "note": "原文：秋，七月，张从宾攻汜水，杀巡检使宋廷浩。；核对说明：本年《资治通鉴》明示死亡，具体死因见对应事件；既有主体旧档案不覆写，补独立死年事实。", "status": "draft", "id": "640f0487-8cdf-5f26-8ebb-f4a610df3367", "subject_id": "33e3df11-a84b-5a7d-8dd6-06f3e1b4ae4d", "source_id": "e84d096f-85d1-5bb4-8532-79f46629b49b"}, {"subject_table": "person", "field_path": "death_year", "claim_text": "尹晖于937年七月条所记事件中死亡。", "citation": "卷281·后晋天福二年（937；七月条下）·zztj-v281-y0937-p036·原文件第41行", "note": "原文：晖将奔吴，为人所杀。；核对说明：本年《资治通鉴》明示死亡，具体死因见对